void os_banked_call(uint16_t cpu_addr) {
  os_bump_step();
  uint8_t page = g_hw.mmu.bank_a & 0x1F;
  uint16_t off;
  if (cpu_addr >= 0x8000 && cpu_addr < 0xC000) off = (uint16_t)(cpu_addr - 0x8000);
  else if (cpu_addr >= 0x4000 && cpu_addr < 0x8000) off = (uint16_t)(cpu_addr - 0x4000);
  else { fprintf(stderr, "os_banked_call: ignore %04X\n", cpu_addr); return; }
  uint16_t bank_addr = (uint16_t)(0x4000 + off);
  /* Boot vector always page 1F continue. */
  if (cpu_addr == 0x80D5 || bank_addr == 0x40D5) page = 0x1F;
  if (!os_enter_page_addr(page, bank_addr)) {
    static int once;
    if (once < 8) {
      fprintf(stderr, "os_banked_call: unhandled %04X (page=%02X bank=%04X)\n", cpu_addr, page, bank_addr);
      once++;
    }
  }
}

void os_jp_hl(void) {
  uint16_t t = hl();
  if (t < 0x4000) {
    if (!os_enter_page_addr(0, t)) {
      static int once;
      if (once < 4) { fprintf(stderr, "os_jp_hl: unhandled %04X\n", t); once++; }
    }
  } else {
    os_banked_call(t);
  }
}

void os_jp_ix(void) { set_hl(ix); os_jp_hl(); }
void os_jp_iy(void) { set_hl(iy); os_jp_hl(); }

